begin;
create table public.hfos_intrinsic_environment_configuration(singleton boolean primary key default true check(singleton),environment text not null check(environment in('STAGING','PRODUCTION')),project_ref text not null check(project_ref~'^[a-z]{20}$'),release_gate text not null check(release_gate in('BLOCKED','OPEN')),installed_at timestamptz not null default clock_timestamp(),installed_by uuid not null references auth.users(id) on update restrict on delete restrict);
create table public.staging_disposable_participant_fixtures(id uuid primary key default gen_random_uuid(),request_id uuid not null unique,auth_user_id uuid not null unique references auth.users(id) on update restrict on delete restrict,participant_id uuid not null unique references public.participants(id) on update restrict on delete restrict,synthetic_email text not null unique,fixture_type text not null default 'DISPOSABLE_E2E_FIXTURE' check(fixture_type='DISPOSABLE_E2E_FIXTURE'),fixture_status text not null default 'ACTIVE' check(fixture_status in('ACTIVE','REVOCATION_PENDING','REVOKED')),created_by uuid not null references auth.users(id) on update restrict on delete restrict,created_at timestamptz not null default clock_timestamp(),revoked_by uuid references auth.users(id) on update restrict on delete restrict,revoked_at timestamptz,check(synthetic_email='hfos-disposable-e2e-'||request_id::text||'@synthetic.invalid'),check((fixture_status in('ACTIVE','REVOCATION_PENDING')and revoked_by is null and revoked_at is null)or(fixture_status='REVOKED' and revoked_by is not null and revoked_at is not null)));
create table public.staging_disposable_participant_fixture_events(id uuid primary key default gen_random_uuid(),fixture_id uuid not null references public.staging_disposable_participant_fixtures(id) on update restrict on delete restrict,event_type text not null check(event_type in('PROVISIONED','REVOCATION_STARTED','REVOKED')),actor_user_id uuid not null references auth.users(id) on update restrict on delete restrict,occurred_at timestamptz not null default clock_timestamp(),event_details jsonb not null default '{}' check(jsonb_typeof(event_details)='object'));
create table public.staging_disposable_auth_orphans(id uuid primary key default gen_random_uuid(),request_id uuid not null unique,auth_user_id uuid not null unique,synthetic_email text not null unique,orphan_status text not null check(orphan_status in('BANNED_PENDING_DELETION','BLOCK_STATUS_UNVERIFIED_HIGH_SEVERITY','AUTH_DELETED_PENDING_FINALIZATION','RESOLVED')),created_by uuid not null references auth.users(id) on update restrict on delete restrict,created_at timestamptz not null default clock_timestamp(),auth_deleted_at timestamptz,resolved_by uuid references auth.users(id) on update restrict on delete restrict,resolved_at timestamptz,check(synthetic_email='hfos-disposable-e2e-'||request_id::text||'@synthetic.invalid'),check((orphan_status in('BANNED_PENDING_DELETION','BLOCK_STATUS_UNVERIFIED_HIGH_SEVERITY')and auth_deleted_at is null and resolved_at is null)or(orphan_status='AUTH_DELETED_PENDING_FINALIZATION'and auth_deleted_at is not null and resolved_at is null)or(orphan_status='RESOLVED'and auth_deleted_at is not null and resolved_at is not null and resolved_by is not null)));
create table public.staging_disposable_auth_orphan_events(id uuid primary key default gen_random_uuid(),orphan_id uuid not null references public.staging_disposable_auth_orphans(id) on update restrict on delete restrict,event_type text not null check(event_type in('ORPHAN_RECORDED','AUTH_DELETION_CONFIRMED','ORPHAN_RESOLVED')),actor_user_id uuid not null references auth.users(id) on update restrict on delete restrict,occurred_at timestamptz not null default clock_timestamp(),event_details jsonb not null default '{}' check(jsonb_typeof(event_details)='object'));
alter table public.hfos_intrinsic_environment_configuration enable row level security;alter table public.hfos_intrinsic_environment_configuration force row level security;alter table public.staging_disposable_participant_fixtures enable row level security;alter table public.staging_disposable_participant_fixtures force row level security;alter table public.staging_disposable_participant_fixture_events enable row level security;alter table public.staging_disposable_participant_fixture_events force row level security;alter table public.staging_disposable_auth_orphans enable row level security;alter table public.staging_disposable_auth_orphans force row level security;alter table public.staging_disposable_auth_orphan_events enable row level security;alter table public.staging_disposable_auth_orphan_events force row level security;
create function public.prevent_disposable_control_mutation()returns trigger language plpgsql set search_path=public,pg_catalog as $$begin raise exception using errcode='P1001',message='Disposable fixture control history is immutable.';end$$;
create trigger hfos_intrinsic_environment_immutable before update or delete on public.hfos_intrinsic_environment_configuration for each row execute function public.prevent_disposable_control_mutation();create trigger staging_disposable_fixture_events_immutable before update or delete on public.staging_disposable_participant_fixture_events for each row execute function public.prevent_disposable_control_mutation();create trigger staging_disposable_orphan_events_immutable before update or delete on public.staging_disposable_auth_orphan_events for each row execute function public.prevent_disposable_control_mutation();
create function public.assert_disposable_intrinsic_staging_boundary()returns void language plpgsql stable security definer set search_path=public,pg_catalog as $$begin if(select count(*)from public.hfos_intrinsic_environment_configuration)<>1 or not exists(select 1 from public.hfos_intrinsic_environment_configuration where singleton and environment='STAGING'and project_ref='dllefpzhmelflbmopdas'and release_gate='BLOCKED')then raise exception using errcode='P1001',message='Intrinsic disposable fixture staging authority is absent or mismatched.';end if;end$$;
create function public.assert_disposable_administrator(p_actor uuid)returns void language plpgsql stable security definer set search_path=public,pg_catalog as $$begin if not exists(select 1 from public.staff_members sm join public.staff_member_roles smr on smr.staff_member_id=sm.id and smr.is_active=true and(smr.expires_at is null or smr.expires_at>clock_timestamp())join public.staff_roles sr on sr.id=smr.staff_role_id and sr.is_active=true and sr.role_code='administrator'where sm.auth_user_id=p_actor and sm.status='active'and sm.deleted_at is null)then raise exception using errcode='P1001',message='Disposable fixture administrator authorization is required.';end if;end$$;
create function public.get_staging_disposable_fixture_by_request(p_request_id uuid,p_actor_user_id uuid)returns table(fixture_id uuid,auth_user_id uuid,participant_id uuid,participant_code text,synthetic_email text,fixture_status text,created_at timestamptz)language plpgsql stable security definer set search_path=public,pg_catalog as $$begin perform public.assert_disposable_intrinsic_staging_boundary();perform public.assert_disposable_administrator(p_actor_user_id);if exists(select 1 from public.staging_disposable_auth_orphans o where o.request_id=p_request_id and o.orphan_status<>'RESOLVED')then raise exception using errcode='P1001',message='Disposable fixture request is blocked by Auth recovery.';end if;return query select f.id,f.auth_user_id,f.participant_id,p.participant_code,f.synthetic_email,f.fixture_status,f.created_at from public.staging_disposable_participant_fixtures f join public.participants p on p.id=f.participant_id where f.request_id=p_request_id;end$$;
create function public.register_staging_disposable_participant(p_request_id uuid,p_auth_user_id uuid,p_synthetic_email text,p_actor_user_id uuid)returns table(fixture_id uuid,auth_user_id uuid,participant_id uuid,participant_code text,synthetic_email text,fixture_status text,created_at timestamptz)language plpgsql security definer set search_path=public,pg_catalog as $$declare v_participant public.participants%rowtype;v_fixture public.staging_disposable_participant_fixtures%rowtype;v_now timestamptz:=clock_timestamp();begin perform public.assert_disposable_intrinsic_staging_boundary();perform public.assert_disposable_administrator(p_actor_user_id);if p_request_id is null or p_auth_user_id is null or lower(p_synthetic_email)<>'hfos-disposable-e2e-'||p_request_id::text||'@synthetic.invalid'then raise exception using errcode='P1001',message='Disposable fixture identity is invalid.';end if;if exists(select 1 from public.staging_disposable_auth_orphans o where(o.request_id=p_request_id or o.auth_user_id=p_auth_user_id)and o.orphan_status<>'RESOLVED')then raise exception using errcode='P1001',message='Disposable fixture request is blocked by Auth recovery.';end if;if not exists(select 1 from auth.users u where u.id=p_auth_user_id and lower(u.email)=lower(p_synthetic_email)and u.deleted_at is null and u.raw_app_meta_data->>'hfos_environment'='STAGING'and u.raw_app_meta_data->>'hfos_fixture'='DISPOSABLE_E2E_FIXTURE'and u.raw_app_meta_data->>'hfos_fixture_request_id'=p_request_id::text)then raise exception using errcode='P1001',message='Disposable fixture Auth provenance is invalid.';end if;select*into v_fixture from public.staging_disposable_participant_fixtures f where f.request_id=p_request_id for update;if found then if v_fixture.fixture_status<>'ACTIVE'or v_fixture.auth_user_id<>p_auth_user_id then raise exception using errcode='P1001',message='Disposable fixture request is not active.';end if;return query select f.id,f.auth_user_id,f.participant_id,p.participant_code,f.synthetic_email,f.fixture_status,f.created_at from public.staging_disposable_participant_fixtures f join public.participants p on p.id=f.participant_id where f.id=v_fixture.id;return;end if;insert into public.participants(auth_user_id,lifecycle_status,research_status,created_by,updated_by,created_at,updated_at)values(p_auth_user_id,'pending_enrollment','not_enrolled',p_actor_user_id,p_actor_user_id,v_now,v_now)returning*into v_participant;insert into public.participant_profiles(participant_id,first_name,last_name,preferred_name,email,profile_completed,created_by,updated_by,created_at,updated_at)values(v_participant.id,'Disposable','Participant','Synthetic E2E',lower(p_synthetic_email),false,p_actor_user_id,p_actor_user_id,v_now,v_now);insert into public.staging_disposable_participant_fixtures(request_id,auth_user_id,participant_id,synthetic_email,created_by,created_at)values(p_request_id,p_auth_user_id,v_participant.id,lower(p_synthetic_email),p_actor_user_id,v_now)returning*into v_fixture;insert into public.staging_disposable_participant_fixture_events(fixture_id,event_type,actor_user_id,occurred_at,event_details)values(v_fixture.id,'PROVISIONED',p_actor_user_id,v_now,jsonb_build_object('lifecycle_status','pending_enrollment','research_status','not_enrolled','profile_completed',false));return query select v_fixture.id,v_fixture.auth_user_id,v_participant.id,v_participant.participant_code,v_fixture.synthetic_email,v_fixture.fixture_status,v_fixture.created_at;exception when unique_violation then raise exception using errcode='P1001',message='Disposable fixture request already exists.';when sqlstate'P1001'then raise;when others then raise exception using errcode='P1002',message='Disposable fixture could not be registered.';end$$;
create function public.list_staging_disposable_participants(p_actor_user_id uuid)returns table(fixture_id uuid,participant_code text,synthetic_email text,fixture_status text,created_at timestamptz,revoked_at timestamptz)language plpgsql stable security definer set search_path=public,pg_catalog as $$begin perform public.assert_disposable_intrinsic_staging_boundary();perform public.assert_disposable_administrator(p_actor_user_id);return query select f.id,p.participant_code,f.synthetic_email,f.fixture_status,f.created_at,f.revoked_at from public.staging_disposable_participant_fixtures f join public.participants p on p.id=f.participant_id order by f.created_at desc;end$$;
create or replace function public.assert_disposable_cleanup_admissible(p_fixture_id uuid,p_actor_user_id uuid)returns table(auth_user_id uuid,participant_id uuid,participant_code text,synthetic_email text,request_id uuid,created_at timestamptz)language plpgsql stable security definer set search_path=public,pg_catalog as $$declare v public.staging_disposable_participant_fixtures%rowtype;begin perform public.assert_disposable_intrinsic_staging_boundary();perform public.assert_disposable_administrator(p_actor_user_id);select*into v from public.staging_disposable_participant_fixtures f where f.id=p_fixture_id and f.fixture_type='DISPOSABLE_E2E_FIXTURE'and f.fixture_status in('ACTIVE','REVOCATION_PENDING');if not found then raise exception using errcode='P1001',message='Disposable fixture is not cleanup-eligible.';end if;if exists(select 1 from public.participant_research_identities x where x.participant_id=v.participant_id)or exists(select 1 from public.assessment_sessions x where x.participant_id=v.participant_id)or exists(select 1 from public.assessments x where x.participant_id=v.participant_id)or exists(select 1 from public.preliminary_reports x where x.participant_id=v.participant_id)or exists(select 1 from public.consents x where x.participant_id=v.participant_id)or exists(select 1 from public.participant_invitations x where x.participant_id=v.participant_id or x.auth_user_id=v.auth_user_id)or exists(select 1 from public.participant_lifecycle_history x where x.participant_id=v.participant_id)or exists(select 1 from public.hfos_measurement_runs x where x.participant_id=v.participant_id)or exists(select 1 from public.hfos_current_measurement_runs x where x.participant_id=v.participant_id)or exists(select 1 from public.hfos_measurement_audit_log x where x.participant_id=v.participant_id)or exists(select 1 from public.evidence_upload_reservations x where x.participant_id=v.participant_id)or exists(select 1 from public.applications x where x.id=(select application_id from public.participants where id=v.participant_id)or x.auth_user_id=v.auth_user_id)or exists(select 1 from public.staff_members x where x.auth_user_id=v.auth_user_id)or exists(select 1 from public.participant_profiles x where x.participant_id<>v.participant_id and x.auth_user_id=v.auth_user_id)then raise exception using errcode='P1001',message='Disposable fixture has governed records and cannot be cleaned up.';end if;return query select v.auth_user_id,v.participant_id,p.participant_code,v.synthetic_email,v.request_id,v.created_at from public.participants p where p.id=v.participant_id;end$$;
create function public.begin_staging_disposable_cleanup(p_fixture_id uuid,p_actor_user_id uuid)returns table(auth_user_id uuid,participant_id uuid,participant_code text,synthetic_email text,request_id uuid,created_at timestamptz)language plpgsql security definer set search_path=public,pg_catalog as $$declare v public.staging_disposable_participant_fixtures%rowtype;v_now timestamptz:=clock_timestamp();begin perform public.assert_disposable_intrinsic_staging_boundary();perform public.assert_disposable_administrator(p_actor_user_id);select*into v from public.staging_disposable_participant_fixtures f where f.id=p_fixture_id for update;if not found or v.fixture_status not in('ACTIVE','REVOCATION_PENDING')then raise exception using errcode='P1001',message='Disposable fixture cannot enter cleanup.';end if;perform*from public.assert_disposable_cleanup_admissible(p_fixture_id,p_actor_user_id);if v.fixture_status='ACTIVE'then update public.staging_disposable_participant_fixtures set fixture_status='REVOCATION_PENDING'where id=v.id;insert into public.staging_disposable_participant_fixture_events(fixture_id,event_type,actor_user_id,occurred_at,event_details)values(v.id,'REVOCATION_STARTED',p_actor_user_id,v_now,jsonb_build_object('auth_access','BLOCK_REQUIRED','credential_stored',false));end if;return query select v.auth_user_id,v.participant_id,p.participant_code,v.synthetic_email,v.request_id,v.created_at from public.participants p where p.id=v.participant_id;end$$;
create function public.finalize_staging_disposable_cleanup(p_fixture_id uuid,p_actor_user_id uuid)returns table(fixture_id uuid,fixture_status text,revoked_at timestamptz)language plpgsql security definer set search_path=public,pg_catalog as $$declare v public.staging_disposable_participant_fixtures%rowtype;v_now timestamptz:=clock_timestamp();begin perform public.assert_disposable_intrinsic_staging_boundary();perform public.assert_disposable_administrator(p_actor_user_id);select*into v from public.staging_disposable_participant_fixtures f where f.id=p_fixture_id for update;if not found or v.fixture_type<>'DISPOSABLE_E2E_FIXTURE'or v.fixture_status<>'REVOCATION_PENDING'then raise exception using errcode='P1001',message='Disposable fixture cleanup is not pending.';end if;perform*from public.assert_disposable_cleanup_admissible(p_fixture_id,p_actor_user_id);update public.participant_profiles set deleted_at=v_now,updated_at=v_now,updated_by=p_actor_user_id where participant_id=v.participant_id and deleted_at is null;update public.participants set deleted_at=v_now,updated_at=v_now,updated_by=p_actor_user_id where id=v.participant_id and deleted_at is null;update public.staging_disposable_participant_fixtures as target set fixture_status='REVOKED',revoked_by=p_actor_user_id,revoked_at=v_now where target.id=v.id and target.fixture_status='REVOCATION_PENDING';if not found then raise exception using errcode='P1001',message='Disposable fixture cleanup is not pending.';end if;insert into public.staging_disposable_participant_fixture_events(fixture_id,event_type,actor_user_id,occurred_at,event_details)values(v.id,'REVOKED',p_actor_user_id,v_now,jsonb_build_object('auth_access','BANNED','participant_record','SOFT_DELETED','profile_record','SOFT_DELETED'));return query select v.id,'REVOKED'::text,v_now;end$$;
create function public.record_staging_disposable_auth_orphan(p_request_id uuid,p_auth_user_id uuid,p_synthetic_email text,p_actor_user_id uuid)returns table(orphan_id uuid,orphan_status text,synthetic_email text,created_at timestamptz)language plpgsql security definer set search_path=public,pg_catalog as $$declare v public.staging_disposable_auth_orphans%rowtype;v_now timestamptz:=clock_timestamp();v_status text;begin perform public.assert_disposable_intrinsic_staging_boundary();perform public.assert_disposable_administrator(p_actor_user_id);if p_synthetic_email<>'hfos-disposable-e2e-'||p_request_id::text||'@synthetic.invalid'or not exists(select 1 from auth.users u where u.id=p_auth_user_id and lower(u.email)=lower(p_synthetic_email)and u.deleted_at is null and u.raw_app_meta_data->>'hfos_environment'='STAGING'and u.raw_app_meta_data->>'hfos_fixture'='DISPOSABLE_E2E_FIXTURE'and u.raw_app_meta_data->>'hfos_fixture_request_id'=p_request_id::text)then raise exception using errcode='P1001',message='Disposable orphan Auth provenance is invalid.';end if;if exists(select 1 from public.staging_disposable_participant_fixtures f where f.request_id=p_request_id or f.auth_user_id=p_auth_user_id)then raise exception using errcode='P1001',message='Registered fixture cannot become an Auth orphan.';end if;select case when u.banned_until>v_now then'BANNED_PENDING_DELETION'else'BLOCK_STATUS_UNVERIFIED_HIGH_SEVERITY'end into v_status from auth.users u where u.id=p_auth_user_id;insert into public.staging_disposable_auth_orphans(request_id,auth_user_id,synthetic_email,orphan_status,created_by,created_at)values(p_request_id,p_auth_user_id,lower(p_synthetic_email),v_status,p_actor_user_id,v_now)on conflict(request_id)do nothing;select*into v from public.staging_disposable_auth_orphans o where o.request_id=p_request_id for update;if v.auth_user_id<>p_auth_user_id then raise exception using errcode='P1001',message='Disposable orphan request identity conflicts.';end if;if not exists(select 1 from public.staging_disposable_auth_orphan_events e where e.orphan_id=v.id and e.event_type='ORPHAN_RECORDED')then insert into public.staging_disposable_auth_orphan_events(orphan_id,event_type,actor_user_id,occurred_at,event_details)values(v.id,'ORPHAN_RECORDED',p_actor_user_id,v_now,jsonb_build_object('auth_access',v.orphan_status,'severity',case when v.orphan_status like'%HIGH_SEVERITY'then'HIGH'else'CONTROLLED'end,'credential_stored',false));end if;return query select v.id,v.orphan_status,v.synthetic_email,v.created_at;end$$;
create function public.list_staging_disposable_auth_orphans(p_actor_user_id uuid)returns table(orphan_id uuid,auth_user_id uuid,request_id uuid,synthetic_email text,orphan_status text,created_at timestamptz,resolved_at timestamptz)language plpgsql stable security definer set search_path=public,pg_catalog as $$begin perform public.assert_disposable_intrinsic_staging_boundary();perform public.assert_disposable_administrator(p_actor_user_id);return query select o.id,o.auth_user_id,o.request_id,o.synthetic_email,o.orphan_status,o.created_at,o.resolved_at from public.staging_disposable_auth_orphans o order by o.created_at desc;end$$;
create function public.mark_staging_disposable_orphan_auth_deleted(p_orphan_id uuid,p_auth_user_id uuid,p_actor_user_id uuid)returns void language plpgsql security definer set search_path=public,pg_catalog as $$declare v public.staging_disposable_auth_orphans%rowtype;v_now timestamptz:=clock_timestamp();begin perform public.assert_disposable_intrinsic_staging_boundary();perform public.assert_disposable_administrator(p_actor_user_id);select*into v from public.staging_disposable_auth_orphans o where o.id=p_orphan_id for update;if not found or v.auth_user_id<>p_auth_user_id then raise exception using errcode='P1001',message='Disposable Auth orphan identity mismatch.';end if;if v.orphan_status in('RESOLVED','AUTH_DELETED_PENDING_FINALIZATION')then return;end if;if exists(select 1 from auth.users u where u.id=v.auth_user_id)then raise exception using errcode='P1001',message='Disposable Auth identity still exists.';end if;update public.staging_disposable_auth_orphans set orphan_status='AUTH_DELETED_PENDING_FINALIZATION',auth_deleted_at=v_now where id=v.id;insert into public.staging_disposable_auth_orphan_events(orphan_id,event_type,actor_user_id,occurred_at,event_details)values(v.id,'AUTH_DELETION_CONFIRMED',p_actor_user_id,v_now,jsonb_build_object('auth_identity','ABSENT','credential_stored',false));end$$;
create function public.finalize_staging_disposable_auth_orphan(p_orphan_id uuid,p_auth_user_id uuid,p_actor_user_id uuid)returns void language plpgsql security definer set search_path=public,pg_catalog as $$declare v public.staging_disposable_auth_orphans%rowtype;v_now timestamptz:=clock_timestamp();begin perform public.assert_disposable_intrinsic_staging_boundary();perform public.assert_disposable_administrator(p_actor_user_id);select*into v from public.staging_disposable_auth_orphans o where o.id=p_orphan_id for update;if not found or v.auth_user_id<>p_auth_user_id then raise exception using errcode='P1001',message='Disposable Auth orphan identity mismatch.';end if;if v.orphan_status='RESOLVED'then return;end if;if v.orphan_status<>'AUTH_DELETED_PENDING_FINALIZATION'or exists(select 1 from auth.users u where u.id=v.auth_user_id)then raise exception using errcode='P1001',message='Disposable Auth deletion is not confirmed.';end if;update public.staging_disposable_auth_orphans set orphan_status='RESOLVED',resolved_by=p_actor_user_id,resolved_at=v_now where id=v.id and orphan_status='AUTH_DELETED_PENDING_FINALIZATION';insert into public.staging_disposable_auth_orphan_events(orphan_id,event_type,actor_user_id,occurred_at,event_details)values(v.id,'ORPHAN_RESOLVED',p_actor_user_id,v_now,jsonb_build_object('auth_identity','ABSENT','credential_stored',false));end$$;
alter function public.prevent_disposable_control_mutation()owner to postgres;alter function public.assert_disposable_intrinsic_staging_boundary()owner to postgres;alter function public.assert_disposable_administrator(uuid)owner to postgres;alter function public.get_staging_disposable_fixture_by_request(uuid,uuid)owner to postgres;alter function public.register_staging_disposable_participant(uuid,uuid,text,uuid)owner to postgres;alter function public.list_staging_disposable_participants(uuid)owner to postgres;alter function public.assert_disposable_cleanup_admissible(uuid,uuid)owner to postgres;alter function public.begin_staging_disposable_cleanup(uuid,uuid)owner to postgres;alter function public.finalize_staging_disposable_cleanup(uuid,uuid)owner to postgres;alter function public.record_staging_disposable_auth_orphan(uuid,uuid,text,uuid)owner to postgres;alter function public.list_staging_disposable_auth_orphans(uuid)owner to postgres;alter function public.mark_staging_disposable_orphan_auth_deleted(uuid,uuid,uuid)owner to postgres;alter function public.finalize_staging_disposable_auth_orphan(uuid,uuid,uuid)owner to postgres;
revoke all on public.hfos_intrinsic_environment_configuration,public.staging_disposable_participant_fixtures,public.staging_disposable_participant_fixture_events,public.staging_disposable_auth_orphans,public.staging_disposable_auth_orphan_events from public,anon,authenticated,service_role;revoke all on function public.prevent_disposable_control_mutation(),public.assert_disposable_intrinsic_staging_boundary(),public.assert_disposable_administrator(uuid),public.get_staging_disposable_fixture_by_request(uuid,uuid),public.register_staging_disposable_participant(uuid,uuid,text,uuid),public.list_staging_disposable_participants(uuid),public.assert_disposable_cleanup_admissible(uuid,uuid),public.begin_staging_disposable_cleanup(uuid,uuid),public.finalize_staging_disposable_cleanup(uuid,uuid),public.record_staging_disposable_auth_orphan(uuid,uuid,text,uuid),public.list_staging_disposable_auth_orphans(uuid),public.mark_staging_disposable_orphan_auth_deleted(uuid,uuid,uuid),public.finalize_staging_disposable_auth_orphan(uuid,uuid,uuid)from public,anon,authenticated,service_role;grant execute on function public.get_staging_disposable_fixture_by_request(uuid,uuid),public.register_staging_disposable_participant(uuid,uuid,text,uuid),public.list_staging_disposable_participants(uuid),public.assert_disposable_cleanup_admissible(uuid,uuid),public.begin_staging_disposable_cleanup(uuid,uuid),public.finalize_staging_disposable_cleanup(uuid,uuid),public.record_staging_disposable_auth_orphan(uuid,uuid,text,uuid),public.list_staging_disposable_auth_orphans(uuid),public.mark_staging_disposable_orphan_auth_deleted(uuid,uuid,uuid),public.finalize_staging_disposable_auth_orphan(uuid,uuid,uuid)to service_role;
comment on table public.hfos_intrinsic_environment_configuration is'Database-owner-held deployment authority; intentionally empty after migration so RPCs fail closed until separately configured in staging.';comment on table public.staging_disposable_auth_orphans is'Recoverable exact Auth compensation state; HIGH_SEVERITY means blocking could not be verified.';
commit;
